def extract(metrics_list, name):
    return np.array([m[name] for m in sorted(metrics_list, key=lambda x: x["generation"])])


def orient(series, name):
    return -series.copy() if name in LOWER_IS_WORSE else series.copy()


def naive_pearson(c, d, cn, dn):
    x, y = orient(c, cn), orient(d, dn)
    n = len(x)
    best_lag, best_r, best_p = 0, 0.0, 1.0
    for lag in range(-MAX_LAG, MAX_LAG + 1):
        if lag >= 0:
            a, b = x[lag:], y[:n - lag]
        else:
            a, b = x[:n + lag], y[-lag:]
        if len(a) < 4:
            continue
        r, p = stats.pearsonr(a, b)
        if abs(r) > abs(best_r):
            best_lag, best_r, best_p = lag, r, p
    return {"method": "naive_pearson", "lag": int(best_lag),
            "r": round(float(best_r), 4), "p_value": round(float(best_p), 6),
            "significant": bool(best_p < ALPHA)}


def diff_xcorr(c, d, cn, dn):
    dx, dy = np.diff(orient(c, cn)), np.diff(orient(d, dn))
    n = len(dx)
    best_lag, best_r, best_p = 0, 0.0, 1.0
    for lag in range(-MAX_LAG, MAX_LAG + 1):
        if lag >= 0:
            a, b = dx[lag:], dy[:n - lag]
        else:
